// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint64 t, uint64 n, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        t = uint64(bound(t, 2, type(uint64).max));
        n = uint64(bound(n, 1, type(uint64).max));

        vm.roll(n);
        vm.warp(t);

        vm.deal(actor, 20 ether);

        // first call: valid (timestamp > pastBlockTime == 0)
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        // second call in the SAME block, SAME timestamp:
        // rule: it must always revert, because the contract stored
        // block.timestamp and require(block.timestamp > pastBlockTime)
        // can no longer hold within the same block.
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        assertFalse(ok2, "second same-block call must revert");
    }
}
